/** Step 3: the joke itself, generated by Cloudflare AI Gateway /ai/run paid with x402 (upto scheme). */
import { defineTool } from '@flue/runtime';
import * as v from 'valibot';
import { config, paidInferenceFetch } from '../lib/env.ts';
import { asJson } from '../lib/json.ts';
import { factsFor, jokeMessages, type JokeInput } from '../lib/joke-prompt.ts';
import { ledger, type PaymentRecord } from '../lib/ledger.ts';
import { logEvent } from '../lib/log.ts';
import { restoreDates, type NewsItem } from '../lib/news.ts';
import { persistJoke } from '../lib/persist.ts';
import { setStep, stepOutput } from '../lib/runs.ts';

export type { JokeInput } from '../lib/joke-prompt.ts';
export { factsFor } from '../lib/joke-prompt.ts';

export interface JokeResult {
	joke: string;
	model: string;
	usage: Record<string, unknown> | null;
	payments: PaymentRecord[];
}

export async function writeJokeFor(input: JokeInput, model = config.jokeModel, conversationId?: string): Promise<JokeResult> {
	const mark = ledger.mark();
	const symbol = input.symbol.toUpperCase();
	const paid = paidInferenceFetch(`AI Gateway joke (${model})`, conversationId);
	const body = JSON.stringify({
		model,
		input: {
			messages: jokeMessages({ ...input, symbol }),
			max_tokens: 400,
			temperature: 1.0,
			// Thinking models (Gemma 4, Qwen 3.8, GLM 4.7) otherwise spend the whole
			// budget reasoning about the joke; gpt-oss honors reasoning_effort instead.
			...(model.startsWith('openai/') ? { reasoning_effort: 'low' } : { chat_template_kwargs: { enable_thinking: false } }),
		},
	});
	// The gateway's facilitator occasionally answers 503 "verify returned 403" on
	// a fresh authorization; one retry after a short pause has always succeeded.
	let res!: Response;
	let text = '';
	for (let attempt = 1; attempt <= 2; attempt++) {
		res = await paid(config.aiRunUrl, {
			method: 'POST',
			headers: { authorization: `Bearer ${config.apiToken}`, 'payment-method': 'x402', 'content-type': 'application/json' },
			body,
		});
		text = await res.text();
		if (res.status < 500 || attempt === 2) break;
		await new Promise((r) => setTimeout(r, 4000));
	}
	let parsed: { success?: boolean; errors?: { message?: string }[]; result?: { choices?: { finish_reason?: string; message?: { content?: string | null; reasoning_content?: string | null } }[]; usage?: Record<string, unknown> } } = {};
	try {
		parsed = JSON.parse(text);
	} catch {
		/* handled below */
	}
	if (!res.ok || !parsed.success) {
		throw new Error(`AI Gateway joke call failed: HTTP ${res.status} ${parsed.errors?.map((e) => e.message).join('; ') ?? text.slice(0, 200)} [cf-ray ${res.headers.get('cf-ray') ?? '-'}]`);
	}
	const message = parsed.result?.choices?.[0]?.message;
	const joke = (message?.content ?? '').trim();
	if (!joke) {
		throw new Error(`AI Gateway (${model}) returned no joke text: finish_reason=${parsed.result?.choices?.[0]?.finish_reason ?? 'unknown'}. Do not call write_joke again; tell the user the joke step failed.`);
	}
	return { joke, model, usage: parsed.result?.usage ?? null, payments: ledger.since(mark) };
}

/** The tool is created per conversation so its output lands on that run's row. */
export const writeJoke = (conversationId: string) =>
	defineTool({
		name: 'write_joke',
		description:
			'Step 3. Pay Cloudflare AI Gateway (x402 machine payments, USDC on Base) to write the joke. Pass news: 2 to 4 one-sentence company news items from search_stock_news (the premise; prefer dated, concrete events); chatter: 0 to 2 trader quotes from fetch_stocktwits_signals, only if funny; price: the latest price; exchange: the exchange from fetch_stocktwits_signals, when it has one. Do not pass counts, tallies, percentages or watchlist sizes. Call this last, exactly once; if it fails, report the failure instead of calling it again.',
		input: v.pipe(
			v.object({
				symbol: v.pipe(v.string(), v.minLength(1), v.maxLength(12)),
				company: v.optional(v.pipe(v.string(), v.maxLength(80))),
				news: v.pipe(v.array(v.pipe(v.string(), v.minLength(1), v.maxLength(300))), v.maxLength(5)),
				chatter: v.optional(v.pipe(v.array(v.pipe(v.string(), v.minLength(1), v.maxLength(300))), v.maxLength(3))),
				price: v.optional(v.pipe(v.string(), v.maxLength(40))),
				exchange: v.optional(v.pipe(v.string(), v.maxLength(40))),
			}),
			v.check((d) => d.news.length + (d.chatter?.length ?? 0) > 0, 'pass at least one news item or trader quote'),
		),
		durable: true,
		async run({ data, step, log }) {
			const symbol = data.symbol.toUpperCase();
			// The company and exchange come from the StockTwits step when the orchestrator
			// leaves them out, so a listed company is never written up as if its IPO were pending.
			const listing = await stepOutput<{ title?: string | null; exchange?: string | null }>(conversationId, 'stocktwits');
			// The dates come back from the Ceramic step of this run: the orchestrator drops or
			// reformats them ("Dec 2025:", "undated:"), and an undated fact reads as today's news.
			const found = await stepOutput<{ results?: NewsItem[] }>(conversationId, 'ceramic');
			const news = restoreDates(data.news, found?.results ?? []);
			const input: JokeInput = { ...data, news, symbol, company: data.company ?? listing?.title ?? null, exchange: data.exchange ?? listing?.exchange ?? null };
			const facts = factsFor(input);
			logEvent('tool.start', true, { tool: 'write_joke', input: data, facts }, { conversationId, label: 'write_joke' });
			await setStep(conversationId, 'write_joke', 'running');
			try {
				const result = await step.do(`joke:${symbol}`, () => writeJokeFor(input, config.jokeModel, conversationId));
				await setStep(conversationId, 'write_joke', 'done', { output: { ...result, input: data, facts, promptFacts: facts } });
				log.info(`Joke from ${result.model}: ${result.joke.slice(0, 80)}…`);
				// Store the joke now: the run's result is this row, not a model reply.
				// The finish hook tops it up with the archive and marks the run done.
				const stored = await persistJoke(conversationId).catch((err) => ({ outcome: 'none' as const, reason: `store failed: ${(err as Error).message.slice(0, 300)}` }));
				if (stored.outcome === 'none') logEvent('error', false, { where: 'write_joke', error: stored.reason }, { conversationId, label: 'store joke' });
				logEvent('tool.done', true, { tool: 'write_joke', model: result.model, stored: stored.outcome, payments: result.payments.length }, { conversationId, label: 'write_joke' });
				// End the agent's turn here. Nothing reads the orchestrator's closing reply
				// (status, feed and permalink come from D1), and that reply was one more
				// paid model turn, the slowest of the run and the one that could still fail.
				return { output: asJson({ ...result, facts }), terminate: true };
			} catch (err) {
				const error = (err as Error).message.slice(0, 400);
				logEvent('tool.error', false, { tool: 'write_joke', error }, { conversationId, label: 'write_joke' });
				await setStep(conversationId, 'write_joke', 'error', { error });
				throw err;
			}
		},
	});
